"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Icon Button: generated by UIX from the design system. Same variants and sizes as the Figma component.

const iconButtonVariants = cva(
  "inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap transition-colors disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 relative p-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md",
  {
    variants: {
      variant: {
        primary: "bg-brand text-fg-on-brand hover:bg-brand-hover active:bg-brand-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid",
        secondary: "bg-secondary text-fg-on-secondary hover:bg-secondary-hover active:bg-secondary-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid",
        soft: "bg-brand-subtle text-fg-brand hover:bg-info-subtle active:bg-muted disabled:bg-disabled disabled:text-fg-disabled",
        outline: "border border-line-default bg-surface text-fg-primary hover:bg-subtle hover:border-line-strong active:bg-muted disabled:bg-disabled disabled:text-fg-disabled",
        ghost: "text-fg-primary hover:bg-subtle active:bg-muted disabled:text-fg-disabled skin-quiet",
        destructive: "bg-danger text-fg-on-danger hover:bg-danger-hover active:bg-danger-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid",
      },
      size: {
        sm: "size-8 text-label-small [&_svg]:size-4",
        md: "size-10 text-label-medium [&_svg]:size-5",
        lg: "size-12 text-label-large [&_svg]:size-5",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "md",
    },
  },
);

export interface IconButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof iconButtonVariants> {
  /** Icon-only buttons need an accessible name. */
  "aria-label": string;
  /** Notification dot on the corner. */
  badgeDot?: boolean;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, type = "button", badgeDot = false, children, ...props }, ref) => (
    <button data-slot="icon-button" data-kind="control" ref={ref} type={type} className={cn(iconButtonVariants({ variant, size }), className)} {...props}>
      {children}
      {badgeDot ? <span aria-hidden className="absolute right-0 top-0 rounded-full ring-2 bg-danger ring-surface size-2" /> : null}
    </button>
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
